#include "physics/mean_simulation.h"
#include <fstream>
#include <iostream>
#include <nlohmann/json.hpp>
#include <stdexcept>
using json=nlohmann::json;
int main(int argc,char**argv){if(argc!=6)return 2;try{json f;std::ifstream(argv[4])>>f;slam::MeanSimulation s(argv[1],argv[2],argv[3]);json cases=json::array();for(unsigned repeat=0;repeat<2;++repeat){s.set_retail_minigame(true);s.reset();s.set_continuous_play(true);s.set_endless_play(false);unsigned tick=0,nudges=0,awards=0,expiry=0;std::uint64_t skull_score=0;json events=json::array();
 auto step=[&](unsigned a){auto count=s.skull_award_count(),bonus=s.bonus_completions();int timer=s.skull_window_ticks();auto score=s.score();auto speed=s.speed_stats().score;s.set_launch(a&8);s.set_flippers(a&1,a&2);if(a&4)s.press_plunger();if(a&16){s.nudge(1,false);++nudges;}if(a&64){s.nudge(-1,false);++nudges;}if(a&32){s.nudge(0,true);++nudges;}if(!s.step()&&!s.game_over())throw std::runtime_error(s.status());s.take_audio_requests();++tick;auto next=s.skull_award_count();if(next>count){unsigned points=next*5000000u;auto&r=s.shared_raw_state().fields;unsigned raw=0;for(unsigned i=0;i<4;++i)raw|=unsigned(r[0x050+i])<<(8*i);if(timer<0||next!=count+1||s.score()<score+points)throw std::runtime_error("Timed Skull award count/score differs");
 if(awards<3){if(raw!=points||s.material5_display_callback()!=0x411544)throw std::runtime_error("Skull initial display differs");}
 else {if(!expiry||next!=1||s.speed_stats().score-speed!=10000000||s.score()-score!=15000000||raw!=10000000||s.material5_display_callback()!=0x410158)throw std::runtime_error("Skull restart/shared SPEED ordering differs");}
 ++awards;skull_score+=points;events.push_back({{"event","award"},{"tick",tick},{"count",next},{"points",points},{"timer_before",timer},{"shared_speed_award",s.speed_stats().score-speed},{"display_callback",s.material5_display_callback()},{"ball",s.ball_number()}});}
 if(timer==0&&count>0&&s.skull_window_ticks()==-1&&bonus==s.bonus_completions()){if(next)throw std::runtime_error("Expired skull count did not reset");if(!expiry)expiry=tick;events.push_back({{"event","expiry"},{"tick",tick}});}
 if(s.bonus_completions()!=bonus)events.push_back({{"event","bonus"},{"tick",tick},{"ball",s.ball_number()},{"score",s.score()}});};
 for(auto&r:f.at("actions_rle"))for(unsigned i=0;i<r.at("ticks").get<unsigned>();++i)step(r.at("actions"));if(tick!=35024||awards!=4||s.skull_award_count()!=1||skull_score!=35000000||expiry!=26900||s.tilted())throw std::runtime_error("Natural5/10/15M/expiry/new5M chain incomplete");while(!s.game_over()&&tick<150000)step(8);if(!s.game_over()||s.ball_count()||!expiry||s.bonus_completions()<3)throw std::runtime_error("Skull expiry/finite lifecycle incomplete");if(tick!=44284||s.score()!=261225260||s.bonus_completions()!=4||awards!=4||skull_score!=35000000||expiry!=26900||nudges!=8)throw std::runtime_error("Skull finite reference differs");const auto score=s.score();const auto bonus=s.bonus_completions();const auto raw=s.shared_raw_state().fields;for(unsigned i=0;i<64;++i){s.press_plunger();s.set_flippers(true,true);if(s.step()||s.score()!=score||s.shared_raw_state().fields!=raw)throw std::runtime_error("Skull GameOver changed");}s.reset();if(s.game_over()||s.score()||s.skull_award_count()||s.skull_window_ticks()!=-1)throw std::runtime_error("Skull newgame reset differs");cases.push_back({{"events",events},{"awards",awards},{"skull_score",skull_score},{"expiry_tick",expiry},{"final_tick",tick},{"final_score",score},{"bonus_completions",bonus},{"nudges",nudges}});
 }if(cases[0]!=cases[1])throw std::runtime_error("Skull fixture nondeterministic");std::ofstream(argv[5])<<json({{"scope","Two fresh legal-input native MillionSkull5/10/15M, actual clock expiry/count reset/new5M, finite bonus/GameOver/freeze/newgame; bounded original components separate from whole trajectory"},{"cases",cases}}).dump(2)<<'\n';std::cout<<"PASS native Skull increasing awards/expiry/finite lifecycle twice\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
